const r="WADA Prohibited List (World Anti-Doping Agency), current edition.",n=[{id:"ashwagandha",name:"Ashwagandha (KSM-66 / Shoden)",category:"supplement",evidence:"weak",status:"OTC herbal supplement (quality varies)",summary:"The best of a weak field. Two 2026 meta-analyses find a real but small testosterone effect (about +10–15%, pooled SMD 0.33), from small and mostly industry-linked trials in novice lifters and overweight middle-aged men. Nobody has tested it in trained men with normal testosterone.",mechanism:"Adaptogenic herb; lowers cortisol and perceived stress in trials and modestly raises testosterone and DHEA.",effects:["Meta-analysis (Zhu 2026, 23 RCTs): total T in men SMD 0.33 (95% CI 0.13–0.54), heterogeneity low (I² 21%); Fornalik 2026 pooled +57 ng/dL. Forge models +12%.","Lopresti 2019 (men 40–70, 8 weeks, crossover): salivary — not serum — T 14.7% above placebo, and the rise did not persist after stopping.","Wankhede 2015 (novice lifters, 8 weeks): T rose 96 vs 18 ng/dL, but the end levels (726 vs 693) did not differ significantly; strength gains were larger.","If your T lab was drawn while taking it, the effect is already in your number and is not added again.","Lower perceived stress (Chandrasekhar 2012)."],risks:["Rare but documented liver injury (case series from Iceland and the US DILIN network): cholestatic injury with jaundice after 2–12 weeks, resolving over 1–5 months.","Can affect thyroid levels; thyrotoxicosis case reports exist. Avoid with hyperthyroidism, and discuss with your doctor if on thyroid medication.","Several European regulators have acted on it: Denmark banned sales after a national risk assessment, the Dutch RIVM advises against it, and the UK FSA says no safe level has been established."],typicalUse:"300 mg twice daily of a standardized root extract (the studied dose)",sources:["Wankhede S, et al. Examining the effect of Withania somnifera supplementation on muscle strength and recovery: a randomized controlled trial. J Int Soc Sports Nutr. 2015;12:43.","Lopresti AL, et al. A randomized, double-blind, placebo-controlled, crossover study examining the hormonal and vitality effects of ashwagandha (Withania somnifera) in aging, overweight males. Am J Mens Health. 2019;13(2):1557988319835985.","Chandrasekhar K, Kapoor J, Anishetty S. A prospective, randomized double-blind, placebo-controlled study of safety and efficacy of a high-concentration full-spectrum extract of ashwagandha root in reducing stress and anxiety in adults. Indian J Psychol Med. 2012;34(3):255-262.","Zhu Y, et al. Efficacy and safety of Withania somnifera: a systematic review and meta-analysis of randomized controlled trials. Front Pharmacol. 2026;17:1799467.","Fornalik M, et al. Withania somnifera supplementation and hormonal outcomes: a systematic review and meta-analysis of randomized controlled trials. Planta Med. 2026.","Björnsson HK, et al. Ashwagandha-induced liver injury: a case series from Iceland and the US Drug-Induced Liver Injury Network. Liver Int. 2020;40(4):825-829.","Morgado A, et al. Systematic review of the use of dietary supplements for male sexual dysfunction and testosterone. Int J Impot Res. 2023."],model:{kind:"tShift",axis:"herbal",dose:{unit:"mg/day",default:600,label:"studied dose",studied:[250,600]},response:[[0,0],[300,.5],[600,1]],tPct:12,tPctLowT:12,rampWeeks:8,tCI:[.4,1.6],ceilingNg:800,e2Pct:null,e2ActionPct:0,shbgDelta:0,bodyComp:"extrapolated",bcMaxLevel:726,bcNote:"No trial has shown that ashwagandha's testosterone rise becomes muscle: Wankhede 2015 measured body composition but its end testosterone did not differ from placebo. Forge runs the modeled rise through the testosterone→lean curve and labels it an extrapolation.",monitor:["Liver panel (ALT/AST/bilirubin) if you take it for more than a few weeks","TSH if you have thyroid disease"],fertility:"No suppression of LH or FSH reported; small trials report better sperm parameters.",timeCourse:"Trials ran 8–16 weeks; the salivary rise in Lopresti 2019 did not persist after stopping.",wada:"Not prohibited.",suits:"Anyone curious about the only supplement with a positive meta-analysis; cheap to try and easy to stop.",notSuits:"Liver disease, hyperthyroidism or thyroid medication; no trial has tested trained men with normal testosterone."}},{id:"tongkat_ali",name:"Tongkat ali (Eurycoma longifolia)",category:"supplement",evidence:"weak",status:"OTC herbal supplement (quality and contamination vary)",summary:"Works only in men who start low. The meta-analysis is positive overall but heavily skewed (I² 87%, publication bias detected), and the subgroup of men with normal testosterone was not significant. Seven of nine trials used one company's extract.",mechanism:"Proposed to increase testosterone release and free T via SHBG; also reduced cortisol in one trial.",effects:["Leisegang 2022 meta-analysis (5 RCTs, 232 men): SMD 1.35 (95% CI 0.57–2.14), but significant only in men with total T under 300 ng/dL, with high heterogeneity and evidence of publication bias.","Chinnappan 2021 (RCT, men 50–70 with T under 300, 12 weeks): about +30 ng/dL vs placebo (roughly +15%); the men stayed below 300, and free T did not differ from placebo.","Forge models +15% if your level is under 350 ng/dL and nothing if it is normal, which is what the trials show."],risks:["Mercury above 0.5 ppm was found in 36 of 100 Malaysian products in one survey, and some products contain none of the active compound. Choose third-party tested.","Insomnia and restlessness reported."],typicalUse:"200–400 mg/day standardized root extract (studied range)",sources:["Leisegang K, et al. Eurycoma longifolia (Jack) improves serum total testosterone in men: a systematic review and meta-analysis of clinical trials. Medicina (Kaunas). 2022;58(8):1047.","Talbott SM, et al. Effect of Tongkat Ali on stress hormones and psychological mood state in moderately stressed subjects. J Int Soc Sports Nutr. 2013;10(1):28.","Henkel RR, et al. Tongkat Ali as a potential herbal supplement for physically active male and female seniors—a pilot study. Phytother Res. 2014;28(4):544-550.","Chinnappan SM, et al. Efficacy of Eurycoma longifolia (Physta) water extract plus multivitamins on quality of life and testosterone in men. Food Nutr Res. 2021;65:5647.","Ang HH, Lee KL, Kiyoshi M. Eurycoma longifolia Jack enhances sexual motivation; heavy metal contamination of Malaysian herbal preparations. J Toxicol Environ Health A / Hum Exp Toxicol. 2004-2006 surveys."],model:{kind:"tShift",dose:{unit:"mg/day",default:200,label:"studied dose",studied:[100,400]},response:[[0,0],[100,.5],[200,1]],tPct:0,tPctLowT:15,rampWeeks:5,axis:"herbal",tCI:[.3,1.7],ceilingNg:400,e2Pct:null,e2ActionPct:0,shbgDelta:0,bodyComp:"extrapolated",bcMaxLevel:350,bcNote:"No tongkat ali trial measured body composition. The modeled rise is run through the testosterone→lean curve and bounded at 350 ng/dL, because Chinnappan 2021's men stayed below 300 and the meta-analysis was only significant below 300.",monitor:["Total testosterone before and after 12 weeks (it only works if you start low)"],fertility:"No suppression; small trials report better sperm motility.",timeCourse:"Trials ran 4–12 weeks.",wada:"Not prohibited.",suits:"Men with a measured total testosterone under about 300 ng/dL who want to try something before a prescription.",notSuits:"Anyone in the normal range (the meta-analysis subgroup was not significant); buy only third-party-tested product (heavy metals).",nullNote:"Your testosterone is in the normal range, and in that subgroup of the meta-analysis the effect was not significant, so Forge models no change."}},{id:"zma",name:"ZMA / zinc / magnesium",category:"supplement",evidence:"weak",status:"OTC dietary supplement",summary:"Useful only if you are actually deficient (heavy sweaters, endurance athletes and restrictive diets are at higher risk). In men with adequate zinc it does nothing for testosterone or training, so Forge models no effect.",mechanism:"Zinc is a cofactor in testosterone production; severe restriction crashes it and repletion restores it. Magnesium is involved in sleep and muscle function, but the testosterone trials are poor.",effects:["Deficiency matters: in Prasad 1996, zinc restriction dropped young men from 1,151 to 306 ng/dL, and repleting marginally deficient older men moved them from 239 to 461 ng/dL. Tiny, uncontrolled samples.","Replete men: no change. ZMA for 8 weeks in resistance-trained men did nothing to hormones, body composition or 1-rep max (Wilborn 2004), and a high-dose zinc study in exercising men with adequate intake found no T change (Koehler 2009).","Magnesium: the one positive study (Cinar 2011) was not randomized or blinded; there is no RCT or meta-analysis in men. Unproven, so not modeled.","Only correcting low zinc raised testosterone in trials, so Forge models no effect."],risks:["Zinc >40 mg/day long-term can cause copper deficiency.","Magnesium can loosen stools.",'Some "test booster" products exceed safe upper limits for zinc, niacin or magnesium (Clemesha 2020).'],typicalUse:"Standard ZMA (30 mg zinc, 450 mg magnesium, 10.5 mg B6) at night, only if intake or a lab is low",sources:["Wilborn CD, et al. Effects of zinc magnesium aspartate (ZMA) supplementation on training adaptations and markers of anabolism and catabolism. J Int Soc Sports Nutr. 2004;1(2):12-20.","Koehler K, et al. Serum testosterone and urinary excretion of steroid hormone metabolites after administration of a high-dose zinc supplement. Eur J Clin Nutr. 2009;63(1):65-70.","Prasad AS, et al. Zinc status and serum testosterone levels of healthy adults. Nutrition. 1996;12(5):344-348.","Te L, et al. The relationship between serum zinc level and testosterone: a systematic review. J Trace Elem Med Biol. 2023;76:127124.","Cinar V, et al. Effects of magnesium supplementation on testosterone levels of athletes and sedentary subjects at rest and after exhaustion. Biol Trace Elem Res. 2011;140(1):18-23.",'Clemesha CG, et al. "Testosterone boosting" supplements composition and claims are not supported by the academic literature. World J Mens Health. 2020;38(1):115-122.'],model:{kind:"tEndogenous",dose:{unit:"mg/day",default:30,label:"elemental zinc in standard ZMA",studied:[15,45]},response:[[0,0],[15,.6],[30,1]],tPct:30,rampWeeks:12,axis:"nutrient",tCI:[.3,1.7],ceilingNg:600,e2Pct:null,e2ActionPct:0,shbgDelta:0,bodyComp:"extrapolated",bcMaxLevel:500,bcNote:"Nobody has measured body composition while repleting zinc. Prasad 1996 moved marginally deficient older men from 239 to 461 ng/dL, so the credit is bounded at 500 ng/dL and labelled an extrapolation.",monitor:["Serum zinc (morning, fasting) before and after","Serum copper if you take more than 40 mg/day for months"],fertility:"Zinc deficiency impairs spermatogenesis; correcting it helps. Supplementing replete men does not.",timeCourse:"Repletion takes weeks to a few months.",wada:"Not prohibited.",suits:"Low zinc intake. Endurance athletes and restrictive diets are the usual cause.",notSuits:"Anyone with a normal zinc level: trials in replete men found nothing.",gate:{deficiencyOnly:"zinc",deficiencyBelow:70}}},{id:"daa",name:"D-aspartic acid (DAA)",category:"supplement",evidence:"refuted",status:"OTC dietary supplement",summary:'The one "test booster" with a result worth knowing: in trained men, 6 g/day LOWERED testosterone about 12%. The famous +42% study was in untrained men recruited at a fertility clinic and was not randomized. Forge models the drop at the high dose and nothing at the low one.',mechanism:"An amino acid that stimulates LH release in rodent tissue. In humans the signal does not survive training status or a control group.",effects:["Melville 2015 (RCT, men with 2+ years of training, 14 days): 6 g/day dropped total T from 590 to 510 ng/dL and free T fell significantly vs placebo. 3 g/day did nothing.","Melville 2017 (RCT, trained men, 12 weeks, 6 g/day): total and free T unchanged, no extra hypertrophy or strength; estradiol fell 16%.","Willoughby 2013 (RCT, resistance-trained men, 3 g/day, 28 days): no change in T, strength or body composition.","Topo 2009 (the +42% study): not randomized, untrained men at an IVF clinic, 12 days."],risks:["No serious adverse events reported, but lowering testosterone is the opposite of the point."],typicalUse:"Not recommended: the trials in trained men show no benefit, and the higher dose lowered testosterone",sources:["Melville GW, Siegler JC, Marshall PW. Three and six grams supplementation of D-aspartic acid in resistance trained men. J Int Soc Sports Nutr. 2015;12:15.","Melville GW, Siegler JC, Marshall PWM. The effects of D-aspartic acid supplementation in resistance-trained men over a three month training period: a randomised controlled trial. PLoS One. 2017;12(8):e0182630.","Willoughby DS, Leutholtz B. D-aspartic acid supplementation combined with 28 days of heavy resistance training has no effect on body composition, muscle strength, and serum hormones. Nutr Res. 2013;33(10):803-810.","Topo E, et al. The role and molecular mechanism of D-aspartic acid in the release and synthesis of LH and testosterone in humans and rats. Reprod Biol Endocrinol. 2009;7:120."],model:{kind:"tShift",dose:{unit:"g/day",default:3,label:"common dose",studied:[3,6]},response:[[0,0],[3,0],[6,1]],tPct:-12.5,tPctLowT:-12.5,rampWeeks:2,axis:"herbal",tCI:[.5,1.5],ceilingNg:2500,e2Pct:null,e2ActionPct:0,shbgDelta:0,bodyComp:"extrapolated",bcMaxLevel:2500,bcNote:"Melville 2017 measured body composition over 12 weeks at 6 g/day and found no extra hypertrophy. The modeled testosterone drop is run through the same curve as any other change, which gives a small negative.",monitor:["Total and free testosterone if you take the 6 g dose"],fertility:"Not studied.",timeCourse:"The drop appeared within 14 days (Melville 2015).",wada:"Not prohibited.",suits:"Nobody, on this evidence.",notSuits:"Trained men: 6 g/day lowered testosterone and 3 g/day did nothing.",nullNote:"At 3 g/day the randomized trials in trained men found no change in testosterone."}},{id:"fenugreek",name:"Fenugreek (Testofen etc.)",category:"supplement",evidence:"weak",status:"OTC herbal supplement",summary:"Pooled analyses show a small total-testosterone effect of very low certainty, and the one trial in trained men found no change in total testosterone, 1-rep max or body fat. Forge models no effect.",mechanism:"Furostanolic saponins are proposed to inhibit aromatase and 5-alpha-reductase. Several trials come from the ingredient makers.",effects:["Isenmann 2023 meta-analysis (7 studies, 449 people): total T SMD 0.32 (95% CI 0.09–0.55); free T 0.24 (−0.04 to 0.52, ns); lean mass 0.19 (−0.10 to 0.49, ns).","Yang 2026 meta-analysis: total T SMD 0.25 (0.02–0.48), GRADE very low.","Wankhede 2016 (RCT, 60 trained men 18–35, 8 weeks): no difference from placebo in total T, 1-rep max or body fat; only free T differed. Manufacturer co-authored."],risks:["Maple-syrup body odour; GI upset; can lower blood sugar (watch it with diabetes medication)."],typicalUse:"600 mg/day of a standardized extract is the studied amount, if you want to try it",sources:["Isenmann E, et al. Effects of fenugreek supplementation on hormones and body composition: a systematic review and meta-analysis. Int J Sports Med. 2023.","Wankhede S, Mohan V, Thakurdesai P. Beneficial effects of fenugreek glycoside supplementation in male subjects during resistance training: a randomized controlled pilot study. J Sport Health Sci. 2016;5(2):176-182.","Mansoori A, et al. Effect of fenugreek extract supplement on testosterone levels in male: a meta-analysis of clinical trials. Phytother Res. 2020;34(7):1550-1555.","Rao A, et al. Testofen, a specialised Trigonella foenum-graecum seed extract, reduces age-related symptoms of androgen decrease. Aging Male. 2016;19(2):134-142."],model:{kind:"none",note:"Pooled effect is small and very low certainty, and total T did not move in the one trial in trained men."}},{id:"boron",name:"Boron",category:"supplement",evidence:"weak",status:"OTC dietary supplement",summary:"The claim rests on one uncontrolled week in eight men. The only randomized trial, in bodybuilders, found nothing. Not modeled.",mechanism:"Proposed to lower SHBG and raise free testosterone; the human data are too thin to say.",effects:["Naghii 2011: 8 men, 10 mg/day for a week, no control group — free T up, estradiol down; magnitudes not reported in the abstract.","Ferrando & Green 1993 (RCT, 19 bodybuilders, 2.5 mg/day, 7 weeks): no change in total T, free T, lean mass or strength."],risks:["Low doses are well tolerated; high intakes can cause nausea and GI upset."],typicalUse:"3–10 mg/day is what the studies used; there is no good reason to expect an effect",sources:["Naghii MR, et al. Comparative effects of daily and weekly boron supplementation on plasma steroid hormones and proinflammatory cytokines. J Trace Elem Med Biol. 2011;25(1):54-58.","Ferrando AA, Green NR. The effect of boron supplementation on lean body mass, plasma testosterone levels, and strength in male bodybuilders. Int J Sport Nutr. 1993;3(2):140-149."],model:{kind:"none",note:"One uncontrolled week in 8 men; the randomized trial was null."}},{id:"tribulus",name:"Tribulus terrestris",category:"supplement",evidence:"refuted",status:"OTC herbal supplement",summary:"Tested repeatedly and it does not raise testosterone. A systematic review concluded the marketing claims are unsubstantiated.",mechanism:"Marketed as raising LH via protodioscin. Not supported in human trials.",effects:['Qureshi 2014 systematic review (11 studies): "ineffective for increasing testosterone… marketing claims are unsubstantiated".',"Neychev 2005 (RCT, 21 men 20–36, 4 weeks): 454–471 ng/dL on Tribulus vs 512 on placebo, not significant.","Rogerson 2007 (RCT, 22 elite rugby players, 5 weeks): no strength or lean-mass benefit."],risks:["Case reports of liver and kidney injury with high-dose products."],typicalUse:"Not recommended; it does not do what it is sold for",sources:["Qureshi A, Naughton DP, Petroczi A. A systematic review on the herbal extract Tribulus terrestris and the roots of its putative aphrodisiac and performance enhancing effect. J Diet Suppl. 2014;11(1):64-79.","Neychev VK, Mitev VI. The aphrodisiac herb Tribulus terrestris does not influence the androgen production in young men. J Ethnopharmacol. 2005;101(1-3):319-323.","Rogerson S, et al. The effect of five weeks of Tribulus terrestris supplementation on muscle strength and body composition during preseason training in elite rugby league players. J Strength Cond Res. 2007;21(2):348-353."],model:{kind:"none",note:"Randomized trials found no testosterone or performance effect."}},{id:"maca",name:"Maca (Lepidium meyenii)",category:"supplement",evidence:"refuted",status:"OTC herbal supplement / food",summary:"Improves libido in trials, but does so without changing testosterone at all. Nothing to model for muscle.",mechanism:"Unknown; the libido effect is independent of androgens.",effects:["Gonzales 2003 (RCT, 1.5–3 g/day, 12 weeks): no change in testosterone, LH, FSH or estradiol.","Libido improved in the same research group's trials without any hormone change."],risks:["Well tolerated as a food."],typicalUse:"1.5–3 g/day if you want the libido effect; it will not change your hormones",sources:["Gonzales GF, et al. Effect of Lepidium meyenii (Maca), a root with aphrodisiac and fertility-enhancing properties, on serum reproductive hormone levels in adult healthy men. J Endocrinol. 2003;176(1):163-168."],model:{kind:"none",note:"Randomized trials show no hormone change."}},{id:"shilajit",name:"Shilajit (purified)",category:"supplement",evidence:"weak",status:"OTC supplement; heavy-metal contamination is a real concern in Ayurvedic products",summary:"One industry-funded randomized trial in men aged 45–55 reported higher total and free testosterone after 90 days. Nothing has replicated it, and no trial has measured muscle. Not modeled.",mechanism:"Fulvic-acid-rich mineral pitch; mechanism for any androgen effect is unclear.",effects:["Pandit 2016 (RCT, healthy men 45–55, 250 mg twice daily, 90 days): total T, free T and DHEA-S higher than placebo (p<0.05). Effect sizes are not in the abstract, and the trial was funded by the ingredient maker.","No body-composition data at all."],risks:["An analysis of Ayurvedic products bought online found lead, mercury or arsenic in about one in five (Saper 2008). Third-party testing matters here more than for most supplements."],typicalUse:"250 mg twice daily of a purified, third-party-tested product is the studied amount",sources:["Pandit S, et al. Clinical evaluation of purified shilajit on testosterone levels in healthy volunteers. Andrologia. 2016;48(5):570-575.","Saper RB, et al. Lead, mercury, and arsenic in US- and Indian-manufactured Ayurvedic medicines sold via the Internet. JAMA. 2008;300(8):915-923."],model:{kind:"none",note:"One unreplicated industry trial; no body-composition data."}},{id:"dhea",name:"DHEA",category:"supplement",evidence:"refuted",status:"OTC in the US; a prohibited anabolic agent on the WADA list at all times",summary:"Raises androstenedione, not testosterone, in young men, and two years of it in older men changed nothing about body composition or strength. Banned in drug-tested sport.",mechanism:"An adrenal precursor hormone. Conversion to testosterone is minimal in men with working testes.",effects:["Brown 1999 (RCT, men around 23, 150 mg/day during 8 weeks of training): total and free T unchanged, androstenedione +150%, and strength and lean-mass gains the same as placebo.","Nair 2006 (RCT, 87 elderly men with low DHEA-S and low T, 2 years): no effect on body composition, strength, VO2peak or quality of life.","Li 2020 meta-analysis: pooled total T in men about +21 ng/dL — within assay noise at a normal level."],risks:["Acne, oily skin, hair loss; converts to estrogens as well as androgens.","WADA prohibited at all times as an anabolic agent; a positive test is a sanction."],typicalUse:"No evidence-based use for muscle in men with normal testes",sources:["Brown GA, et al. Effect of oral DHEA on serum testosterone and adaptations to resistance training in young men. J Appl Physiol. 1999;87(6):2274-2283.","Nair KS, et al. DHEA in elderly women and DHEA or testosterone in elderly men. N Engl J Med. 2006;355(16):1647-1659.","Li Y, et al. Effects of DHEA supplementation on testosterone concentrations: a systematic review and meta-analysis. Exp Gerontol. 2020;140:111110.",r],model:{kind:"none",note:"No testosterone or body-composition effect in men with working testes."}},{id:"forskolin",name:"Forskolin (Coleus forskohlii)",category:"supplement",evidence:"weak",status:"OTC dietary supplement",summary:"One small trial in overweight men found less body fat and higher free testosterone, but the total-testosterone change was not statistically significant and lean mass was only a trend. Never replicated. Not modeled.",mechanism:"Activates adenylate cyclase, raising cyclic AMP, which in theory increases lipolysis and steroidogenesis.",effects:["Godard 2005 (RCT, 30 men with BMI ≥26, 12 weeks): total T +16.8 ± 33.8% vs −1.1 ± 18.4%, not significant; free T rose significantly; body fat and fat mass fell on DXA; lean mass was a trend (p=0.097)."],risks:["Can lower blood pressure and increase heart rate; interacts with blood-pressure and blood-thinning medication."],typicalUse:"250 mg of a 10% extract twice daily is the studied amount",sources:["Godard MP, Johnson BA, Richmond SR. Body composition and hormonal adaptations associated with forskolin consumption in overweight and obese men. Obes Res. 2005;13(8):1335-1343."],model:{kind:"none",note:"One small trial; the total-testosterone change was not significant."}}],s=[{id:"melatonin",name:"Melatonin",category:"supplement",evidence:"moderate",status:"OTC in the US (prescription in many countries); label accuracy varies",summary:'Helps you fall asleep a little sooner (about 7 minutes on average) and helps reset your body clock. It only helps your projection if you actually sleep more, so update "typical sleep" below when that happens.',mechanism:"A circadian timing signal, not a sedative. Most effective for shifted body clocks (late stimulant days, travel).",effects:["Sleep onset ~7 min faster and total sleep ~8 min longer on average (meta-analysis).","No direct effect in the model; sleep hours drive it."],risks:["Products often contain far more or less than labeled (one analysis found −83% to +478%).","Morning grogginess at higher doses; 0.5–3 mg is usually enough."],typicalUse:"0.5–3 mg 30–60 min before bed",sources:["Ferracioli-Oda E, Qawasmi A, Bloch MH. Meta-analysis: melatonin for the treatment of primary sleep disorders. PLoS One. 2013;8(5):e63773.","Erland LA, Saxena PK. Melatonin natural health products and supplements: presence of serotonin and significant variability of melatonin content. J Clin Sleep Med. 2017;13(2):275-281."],model:{kind:"none",note:"Works through your sleep hours."}}],i=[{id:"energy_availability",name:"Eating enough (energy availability)",category:"lifestyle",evidence:"moderate",status:"Free, and the biggest testosterone lever you actually control",summary:"Chronic under-eating is the fastest way for a lean, hard-training man to tank his own testosterone. It also reverses within days to weeks of eating normally again.",mechanism:"Low energy availability suppresses GnRH from the hypothalamus, so LH falls and the testes get no signal. It is a central, reversible shutdown, not testicular damage, and it raises SHBG so free T falls further than total T.",effects:['Friedl 2000 (Ranger course, ~1,000–1,200 kcal/day deficits plus heavy load and sleep loss): testosterone fell to about 130 ng/dL, "approaching castrate", with LH suppressed and IGF-1 halved. Refeeding brought prompt recovery.',"Rossow 2013 (natural bodybuilder, 6-month contest prep to 4.5% body fat): 922 → 227 ng/dL, back to 991 after recovery; strength had not fully returned at 6 months.","Short, mild restriction does far less: 4 days at 15 kcal/kg fat-free mass did not change T in 6 men (Koehler 2016).","Lean mass: a meta-analysis found deficits around 500 kcal/day stop lean-mass gain from lifting altogether (Murphy & Koehler 2021).",'Forge models the recovery from YOUR entered typical deficit (Metabolic values → "typical daily deficit"). The anchors are the two measured extremes — about −10% at 500 kcal/day and roughly −65% at the Ranger/contest-prep end (1,500 kcal/day plus heavy training) — and the points between them are an interpolation, not a measurement.',"It also works through your calorie target in Nutrition and through the warning Forge shows when you are in a deficit."],risks:[],typicalUse:"Keep deficits moderate (roughly 300–500 kcal/day) and protein high",sources:["Friedl KE, et al. Endocrine markers of semistarvation in healthy lean men in a multistressor environment. J Appl Physiol. 2000;88(5):1820-1830.","Rossow LM, et al. Natural bodybuilding competition preparation and recovery: a 12-month case study. Int J Sports Physiol Perform. 2013;8(5):582-592.","Koehler K, et al. Low energy availability in exercising men is associated with reduced leptin and insulin but not with changes in other metabolic hormones. J Sports Sci. 2016;34(20):1921-1929.","Areta JL, Taylor HL, Koehler K. Low energy availability: history, definition and evidence of its endocrine, metabolic and physiological effects in prospective studies in males. Eur J Appl Physiol. 2021;121(1):1-21.","Murphy C, Koehler K. Energy deficiency impairs resistance training gains in lean mass but not strength: a meta-analysis and meta-regression. Scand J Med Sci Sports. 2021;31(11):2185-2198."],model:{kind:"tEndogenous",axis:"lifestyle",dose:{unit:"% of the deficit you remove",default:100,label:"as studied (back to maintenance)",studied:[0,100]},response:[[0,0],[100,1]],tPct:100,rampWeeks:4,deficitT:[[0,0],[300,0],[500,10],[1e3,40],[1500,65],[2e3,75]],tCI:[.5,1.5],ceilingNg:1e3,e2Pct:null,e2ActionPct:0,shbgDelta:-5,shbgNote:"Low energy availability raises SHBG, so free testosterone falls further than total; eating enough reverses that (Areta 2021).",bodyComp:"measured",bcMaxLevel:1100,bcNote:"Measured: a 500 kcal/day deficit abolished lean-mass gain from lifting in a meta-analysis of 26 trials (Murphy & Koehler 2021), and the case-study and field data show the testosterone fall reversing with refeeding. Forge models both, and the calorie side already flows through the projection.",monitor:["Morning total testosterone, LH and SHBG if you have been in a deficit for months","Body weight trend: if it is falling you are in one"],fertility:"Central and fully reversible; sperm production recovers with weight and energy intake.",timeCourse:"Days to weeks (Friedl 2000 saw prompt recovery on refeeding while the other stressors continued).",wada:"Not prohibited.",suits:"Lean, hard-training men in a long deficit — and anyone whose appetite is blunted (Adderall, stimulants, high cardio volume).",notSuits:"Anyone eating at or above maintenance: there is nothing to undo, and Forge models zero.",gate:{deficitOnly:!0}}},{id:"fat_loss",name:"Fat loss (if you carry a lot of it)",category:"lifestyle",evidence:"strong",status:"Free; the first step when extra body fat is holding testosterone down",summary:"In men carrying a lot of extra body fat (a BMI of 30 or more), losing weight reliably raises testosterone — about +83 ng/dL from a diet and +252 ng/dL after bariatric surgery, scaling with how much weight comes off. In lean men there is no evidence it does anything, so Forge applies it only when your BMI is 30 or above.",mechanism:"Fat tissue aromatizes testosterone to estradiol, and a lot of it suppresses LH; losing fat reverses both.",effects:["Corona 2013 meta-analysis (24 studies, men with a BMI of 30 or more): low-calorie diet +2.87 nmol/L (95% CI 1.68–4.07) ≈ +83 ng/dL; bariatric surgery +8.73 (6.51–10.95) ≈ +252 ng/dL. The amount of weight lost was the best predictor.","Adding exercise to the diet added nothing on top (Mohseni-Takalloo 2022: −0.03 nmol/L, 95% CI −0.11 to 0.06).","GLP-1 drugs raise testosterone the same way: roughly +72 to +150 ng/dL in men with a high BMI and low testosterone, and meta-regression shows the rise tracks the weight lost, not the drug.","Lean men: no evidence. Low testosterone from body weight was found in only 0.4% of lean men in a large cohort."],risks:["Crash dieting works against you: a large deficit suppresses testosterone in lean men (see Eating enough)."],typicalUse:"A moderate deficit with high protein and lifting, if your BMI is 30 or above",sources:["Corona G, et al. Body weight loss reverts obesity-associated hypogonadotropic hypogonadism: a systematic review and meta-analysis. Eur J Endocrinol. 2013;168(6):829-843.","Grossmann M, Matsumoto AM. A perspective on middle-aged and older men with functional hypogonadism: focus on holistic management. J Clin Endocrinol Metab. 2017;102(3):1067-1075.","Mohseni-Takalloo S, et al. The effect of weight loss interventions with or without exercise on sex hormones in men: a systematic review and meta-analysis. Eur J Endocrinol. 2022;186(1):109-119.","Salvio G, et al. Effects of GLP-1 receptor agonists on sex hormones in men: a systematic review and meta-analysis. Andrology. 2025;13(8):2022-2034."],model:{kind:"tEndogenous",dose:{unit:"% of the studied weight loss",default:100,label:"as studied (~10% of body weight)",studied:[0,100]},response:[[0,0],[100,1]],tPct:28,rampWeeks:24,axis:"lifestyle",tCI:[.58,1.42],ceilingNg:700,e2Pct:-25,e2ActionPct:0,shbgDelta:6,e2Note:"Losing fat removes aromatase tissue, so estradiol falls while testosterone rises. That is a different thing from blocking aromatase with a drug: the estrogen that remains is not blocked, and fat is being lost for ordinary energy-balance reasons.",shbgNote:"SHBG rises with weight loss (insulin falls), so total T rises more than free T (Corona 2013).",bodyComp:"measured",bcMaxLevel:700,bcNote:"Measured end to end: the fat loss itself is what the projection is already simulating. The hormone change is credited on top only up to 700 ng/dL, the top of what diet or surgery produced in Corona 2013.",monitor:["Total testosterone before and after ~10% weight loss","HbA1c, lipids, blood pressure"],fertility:"Improves with weight loss (LH and FSH recover).",timeCourse:"Tracks the weight: months.",wada:"Not prohibited.",suits:"BMI 30 or above. The first step for testosterone held down by body fat in every guideline.",notSuits:"Lean men — there is no evidence it raises testosterone, and a hard deficit lowers it (see Eating enough).",gate:{obesityOnly:!0}}},{id:"endurance_load",name:"High-volume endurance training",category:"lifestyle",evidence:"weak",status:"Free, and relevant if you train big endurance weeks",summary:"Men with years of high-volume endurance training sit about 25–40% lower in resting testosterone than matched untrained men. Add this if you are currently training like that, and Forge will lower the testosterone it assumes for you.",mechanism:"Chronic high training load appears to lower the hypothalamic set-point, often alongside low energy availability. It is mostly cross-sectional evidence, so cause and effect are not nailed down.",effects:["Hackney 1988: 11 endurance-trained men (12 years of training, 6.6 days/week) 499 vs 725 ng/dL in sedentary controls (−31%); free T −27%.","Hooper 2017: 9 runners with low resting testosterone at 265 vs 467 ng/dL (−43%), with energy availability of 27 vs 45 kcal/kg fat-free mass — so under-eating is tangled up in it.","Hackney 2020 review: the drop is defined as a persistent 25–50% reduction and takes years of training to appear; in a cohort of 196 runners it plateaued about 30–35% lower.","It is at least partly reversible: when training volume was cut back in an 18-week study, testosterone returned toward baseline.","Forge models −25%, the conservative end. If you have a real lab drawn during this period, that number wins instead."],risks:["Low testosterone from training load comes with low bone density in some runners; if this is you, it is worth a doctor's visit rather than a supplement."],typicalUse:"Nothing to take. If size is the goal, cutting endurance volume back is the lever",sources:["Hackney AC, Sinning WE, Bruot BC. Reproductive hormonal profiles of endurance-trained and untrained males. Med Sci Sports Exerc. 1988;20(1):60-65.","Hooper DR, et al. Endocrinological roles for testosterone in resistance exercise responses and adaptations. Eur J Appl Physiol. 2017;117(7):1349-1359.","Hackney AC. Hypogonadism in exercising males: dysfunction or adaptive-regulatory adjustment? Front Endocrinol. 2020;11:11.","Hackney AC, Hooper DR. Reductions in testosterone are not indicative of exercise performance decrement in male endurance athletes. Physiol Int. 2019;106(4):324-332."],model:{kind:"tEndogenous",dose:{unit:"% of the studied training load",default:100,label:"as studied (years of near-daily endurance training)",studied:[0,100]},response:[[0,0],[100,1]],tPct:-25,rampWeeks:0,axis:"lifestyle",tCI:[1,1.8],ceilingNg:1e3,e2Pct:null,e2ActionPct:0,shbgDelta:4,shbgNote:"Endurance-trained men run higher SHBG, so free T falls a little more than total (Hackney 1988: free T −27% vs total −31%).",bodyComp:"extrapolated",bcMaxLevel:1100,bcNote:"No trial has randomized endurance volume and measured body composition against testosterone. The modeled drop is run through the same curve as any other change and is labelled an extrapolation.",monitor:["Morning total testosterone and LH","Vitamin D and bone density if this has been going on for years"],fertility:"Usually preserved; the drop is central and partly reversible when volume falls.",timeCourse:"Takes years to appear (Hackney 2020) and improves over months when volume is cut.",wada:"Not prohibited.",suits:"Nothing to take. Add it to see what your current endurance volume is costing you; the lever is cutting the volume.",notSuits:"Anyone not training big endurance weeks."}},{id:"alcohol",name:"Alcohol",category:"lifestyle",evidence:"moderate",status:"Free, and it costs you in both directions",summary:"About three drinks a day for three weeks lowered testosterone roughly 7% in a randomized crossover. Chronic heavy drinking does more. Occasional drinks are not the issue; a daily habit is.",mechanism:"Alcohol suppresses LH and directly impairs testicular steroidogenesis, and raises estradiol. It also costs you sleep quality and training calories.",effects:["Sierksma 2004 (randomized crossover, 10 middle-aged men, ~40 g alcohol/day for 3 weeks): total T −6.8% (95% CI −1.0 to −12.5%).","Santi 2023 meta-analysis (21 studies, 10,199 subjects): lower total T in healthy chronic drinkers, with estradiol higher. The pooled units are ambiguous in the abstract, so Forge does not extrapolate past the randomized number.","Forge models −6.8% at the studied 3 drinks/day and scales linearly below that; above 3 drinks/day it plateaus, because no randomized dose higher than that exists."],risks:["Blunts muscle protein synthesis after training, wrecks sleep quality, and adds calories without protein."],typicalUse:"If size is the goal, keep it occasional rather than daily",sources:["Sierksma A, et al. Effect of moderate alcohol consumption on plasma dehydroepiandrosterone sulfate, testosterone, and estradiol levels in middle-aged men and postmenopausal women. Alcohol Clin Exp Res. 2004;28(5):780-785.","Santi D, et al. Alcohol consumption and testicular function: a systematic review and meta-analysis. Andrology. 2023;11(8):1480-1492."],model:{kind:"tEndogenous",axis:"lifestyle",dose:{unit:"drinks/day",default:3,label:"the randomized dose (≈40 g/day)",studied:[0,3],note:"One drink ≈ 14 g alcohol. Above 3 drinks/day Forge plateaus: no randomized higher dose exists."},response:[[0,0],[3,1]],tPct:-6.8,rampWeeks:3,tCI:[.15,1.84],ceilingNg:1e3,e2Pct:7,e2ActionPct:0,shbgDelta:0,e2Note:"Estradiol rose on alcohol in the same crossover (Sierksma 2004) and in the meta-analysis (Santi 2023).",bodyComp:"extrapolated",bcMaxLevel:1100,bcNote:"No trial has measured body composition against alcohol-induced testosterone change. The modeled drop runs through the testosterone→lean curve and is labelled an extrapolation; the bigger costs (sleep, blunted post-workout protein synthesis, empty calories) are separate.",monitor:["Nothing specific; a morning testosterone after a dry month is the cheapest experiment."],fertility:"Heavy chronic use impairs it; moderate intake has not been shown to.",timeCourse:"The randomized effect appeared over 3 weeks of daily drinking.",wada:"Not prohibited (removed from the WADA list in 2018).",suits:"Daily drinkers. Cutting back is free and the effect reverses.",notSuits:"Occasional drinking is not the issue; the trial was 3 drinks a day for 3 weeks."}},{id:"resistance_training",name:"Lifting itself (resistance training)",category:"lifestyle",evidence:"strong",status:"Free, and the thing that actually builds the muscle",summary:"Lifting is the single biggest driver of muscle in this whole app — and it does NOT raise your resting testosterone. The post-workout hormone spike is real, lasts about half an hour, and does not predict how much muscle you build. Forge models the training, not a hormone effect.",mechanism:"Mechanical tension drives muscle protein synthesis through local, androgen-receptor and mTOR pathways. The acute systemic hormone surge is a side effect of the effort, not the signal.",effects:["Resting testosterone does not change with training: SMD 0.00 (95% CI −0.20 to 0.20) across trials in men 19–75 (Potter 2021 meta-analysis).","The acute spike is large (SMD 0.74) and gone within 30 minutes (D'Andrea 2020).","It does not matter: training one arm in a high-hormone environment and one in a low-hormone environment produced the same growth (West 2010), and no hormone response correlated with gains in 49 trained men (Morton 2016).","What did correlate was muscle androgen-receptor content, not blood hormones (Morton 2018).","Forge models no testosterone effect from lifting. The lean mass it builds comes through the training side of the projection, where it belongs."],risks:[],typicalUse:"The weekly set targets Forge already plans for you",sources:["Potter E, et al. The effect of resistance training on resting testosterone concentrations in men: a systematic review and meta-analysis. Sports Med. 2022;52(5):1091-1105. doi:10.1007/s40279-021-01600-z","D'Andrea S, et al. Endogenous transient doping: physical exercise acutely increases testosterone levels — results from a meta-analysis. J Endocrinol Invest. 2020;43(10):1349-1371. doi:10.1007/s40618-020-01251-3","West DW, et al. Elevations in ostensibly anabolic hormones with resistance exercise enhance neither training-induced muscle hypertrophy nor strength of the elbow flexors. J Appl Physiol. 2010;108(1):60-67. doi:10.1152/japplphysiol.01147.2009","Morton RW, et al. Neither load nor systemic hormones determine resistance training-mediated hypertrophy or strength gains in resistance-trained young men. J Appl Physiol. 2016;121(1):129-138. doi:10.1152/japplphysiol.00154.2016","Morton RW, et al. Muscle androgen receptor content but not systemic hormones is associated with resistance training-induced skeletal muscle hypertrophy in healthy, young men. Front Physiol. 2018;9:1373. doi:10.3389/fphys.2018.01373"],model:{kind:"none",axis:"lifestyle",bodyComp:"none",bcNote:"Measured and null for the hormone pathway: resting testosterone does not change with training (Potter 2021, SMD 0.00). The muscle it builds is modeled by the training side of the projection, not here.",note:"No testosterone effect (Potter 2021: SMD 0.00). Your training already drives the projection."}}],l=Object.freeze([{before:"collagen",items:n},{before:"sleep_hygiene",items:s},{before:"cold_plunge",items:i}]),d=Object.freeze([...n,...s,...i].map(e=>e.id)),c={ashwagandha:{model:{femaleNote:"In women the meta-analysis found no testosterone rise (+5 ng/dL, not significant, vs +57 ng/dL in men; Fornalik 2026), and a trial in perimenopausal women found none (Gopal 2021). Forge models no effect."},sources:["Fornalik M, et al. Hormonal modulation with Withania somnifera: systematic review and meta-analysis of randomized-controlled trials. Planta Med. 2026;92(8):790-805. doi:10.1055/a-2802-8363","Gopal S, et al. Effect of an ashwagandha (Withania somnifera) root extract on climacteric symptoms in women during perimenopause: a randomized, double-blind, placebo-controlled study. J Obstet Gynaecol Res. 2021;47(12):4414-4425. doi:10.1111/jog.15030"]},tongkat_ali:{model:{femaleNote:"No randomized trial in women: the only female data are a small mixed-sex pilot in seniors (Henkel 2014). Forge models no effect."}},zma:{model:{femaleNote:"Correcting a real zinc deficiency matters for health (the female cut-off is ~70 µg/dL, morning fasting; Hotz 2003), but the testosterone evidence is in men. Forge models no muscle effect for women."}},daa:{model:{femaleNote:"Only studied in men (and the higher dose lowered their testosterone). Forge models no effect for women."}},sleep_hygiene:{model:{femaleNote:'The testosterone part is from young men (Leproult 2011), so Forge adds none for women. Sleep still drives the muscle ceiling and how much lean you keep in a deficit (your "typical sleep" setting).'}},energy_availability:{summary:"The most important item for women who train hard and diet: below about 30 kcal per kg of fat-free mass a day (food minus exercise), the hormone pulses that drive the menstrual cycle were disrupted within 5 days. Missed periods, stress fractures and stalled progress follow (IOC REDs consensus).",effects:["Loucks & Thuma 2003 (randomized, 29 regularly menstruating women): LH pulsatility unaffected at 30 kcal/kg lean mass/day, disrupted below it within 5 days.","Hulmi 2017 (27 female physique competitors, 4-month diet to 12.7% body fat): leptin, T3, estradiol and testosterone fell and 63% had irregular bleeding; T3 and testosterone hadn't fully recovered after 3–4 months.","Halliday 2016 (case, drug-free figure competitor): energy availability fell during a 20-week prep, cycles became irregular in the first month and the last period came at week 11.","Forge (women): Nutrition and the projection warn when planned intake minus exercise falls under 30 kcal per kg of your lean mass."],sources:["Loucks AB, Thuma JR. Luteinizing hormone pulsatility is disrupted at a threshold of energy availability in regularly menstruating women. J Clin Endocrinol Metab. 2003;88(1):297-311. doi:10.1210/jc.2002-020369","Mountjoy M, et al. 2023 International Olympic Committee's (IOC) consensus statement on Relative Energy Deficiency in Sport (REDs). Br J Sports Med. 2023;57(17):1073-1097. doi:10.1136/bjsports-2023-106994","Hulmi JJ, et al. The effects of intensive weight reduction on body composition and serum hormones in female fitness competitors. Front Physiol. 2017;7:689. doi:10.3389/fphys.2016.00689","Halliday TM, Loenneke JP, Davy BM. Dietary intake, body composition, and menstrual cycle changes during competition preparation and recovery in a drug-free figure competitor: a case study. Nutrients. 2016;8(11):740. doi:10.3390/nu8110740"]},fat_loss:{model:{femaleNote:"The testosterone rise is a male finding. In women with a high BMI weight loss usually LOWERS excess androgens, which is a health benefit, not a muscle effect. Forge models no testosterone change."}},endurance_load:{summary:"In men, years of high-volume endurance training lower resting testosterone. In women the equivalent risk is low energy availability: missed or irregular periods from not eating enough for the training load (see Eating enough).",model:{femaleNote:"The testosterone drop is a male finding. For women the relevant risk is low energy availability and menstrual disruption (IOC REDs 2023), which Forge warns about in Nutrition and the projection."}},dhea:{summary:"In women DHEA is a real source of testosterone, so it does raise it a little (+17.5 ng/dL in elderly women, Hu 2020), but two years of it changed nothing about body composition or strength (Nair 2006, elderly women). The Endocrine Society advises against routine use (Wierman 2014). Banned in drug-tested sport.",sources:["Hu Q, et al. Impact of dehydroepiandrosterone (DHEA) supplementation on testosterone concentrations and BMI in elderly women: a meta-analysis of randomized controlled trials. Complement Ther Med. 2020;56:102620. doi:10.1016/j.ctim.2020.102620"]},alcohol:{model:{femaleNote:"The randomized crossover (Sierksma 2004) included postmenopausal women, but the testosterone outcome Forge models is the male one. Alcohol still costs sleep, training quality and calories."}},resistance_training:{effects:["Resting testosterone does not change with training in either sex; women build muscle at the same relative rate as men (Roberts 2020; Refalo 2025) despite about 15× less testosterone.","The acute post-workout hormone surge does not predict growth (West 2010; Morton 2016).","Forge models no hormone effect. The lean mass lifting builds comes through the training side of the projection."]}},m={sleep_hygiene:{mechanism:"Sleep loss lowers muscle protein synthesis (−18% after one night without sleep), shifts hormones (less testosterone, more cortisol) and increases hunger.",sources:["Nedeltcheva AV, et al. Insufficient sleep undermines dietary efforts to reduce adiposity. Ann Intern Med. 2010;153(7):435-441.","Lamon S, et al. The effect of acute sleep deprivation on skeletal muscle protein synthesis and the hormonal environment. Physiol Rep. 2021;9(1):e14660.","Watson NF, et al. Recommended amount of sleep for a healthy adult: a joint consensus statement of the American Academy of Sleep Medicine and Sleep Research Society. Sleep. 2015;38(6):843-844.","Knowles OE, et al. Inadequate sleep and muscle strength: implications for resistance training. J Sci Med Sport. 2018;21(9):959-968.","Leproult R, Van Cauter E. Effect of 1 week of sleep restriction on testosterone levels in young healthy men. JAMA. 2011;305(21):2173-2174.","Su L, et al. Effects of sleep deprivation on testosterone in males: a systematic review and meta-analysis. Sleep Med. 2021;88:267-273."],model:{kind:"tEndogenous",dose:{unit:"% of nights",default:100,label:"as studied (every night)",studied:[0,100]},response:[[0,0],[100,1]],tPct:14,rampWeeks:2,axis:"lifestyle",tCI:[.5,1.5],ceilingNg:900,e2Pct:null,e2ActionPct:0,shbgDelta:0,bodyComp:"measured",bcMaxLevel:900,bcNote:"Sleep is the one lifestyle lever with a randomized body-composition result: Nedeltcheva 2010 (5.5 h vs 8.5 h in a deficit) shifted weight loss from fat to lean. Forge models that through the sleep retention and ceiling curves as well as through testosterone, so no extra cap is needed.",monitor:["Nothing. Track hours; a morning testosterone lab after a month of 8 h nights tells you if it mattered."],fertility:"Short sleep lowers testosterone and sperm quality in observational data; fixing it is harmless.",timeCourse:"Leproult 2011 saw the fall within one week, so recovery is fast.",wada:"Not prohibited.",suits:"Anyone averaging under 7 h. The biggest free lever on this list.",notSuits:"Nobody — but if you already sleep 7–9 h there is nothing to recover, and Forge models zero.",gate:{shortSleepOnly:!0,sleepBelow:7,sleepTarget:8,sleepFloor:5}}}},h=", a level that usually costs regular periods",u="; missed periods mean you are under-fuelled",g="At equal calories and protein, dietary fat is not more fattening than carbohydrate (Hall & Guo 2017). Fat eaten in a surplus is stored most efficiently, but a carbohydrate surplus ends up as body fat too, because the carbs are burned in place of the fat you ate. Energy balance decides fat gain; the fat/carb split decides glycogen, water, how training feels and where hormones sit.",p=e=>`Fat is only ${e}% of calories. 20-35% is the usual range (IOM), and 15-30% is fine for a physique athlete (Helms 2014). Going below ~20% for long stretches nudges testosterone down a little (pooled effect −0.38 SD, 95% CI −0.75 to −0.01, in trials comparing ~20% vs ~40% fat; Whittaker 2021) and makes meals less filling. Note the direction: eating MORE fat at the same calories does not make you gain fat — only a calorie surplus does.`,f=(e,t,o)=>`Energy availability ≈${e} kcal per kg of lean mass a day (food ${t} minus exercise ≈${o} kcal). ~45 is adequate and ~30 is where measurable harm starts; the 30 figure was established in women (Loucks & Thuma 2003) and no male threshold has been validated, but low energy availability costs bone, hormones, recovery and training quality in men too (IOC REDs consensus 2023). Eat more around training or ease the deficit.`,y=(e,t,o,a)=>`Energy availability ≈${e} kcal per kg of lean mass a day (food ${t} minus exercise ≈${o} kcal). ${a?"Low energy availability costs bone, recovery and training quality at any age (IOC REDs 2023); ~45 is adequate.":"Below ~30 the hormone pulses that run the menstrual cycle were disrupted within 5 days (Loucks & Thuma 2003); ~45 is adequate."} Eat more on training days or ease the deficit${a?"":", and see a doctor if your periods change (IOC REDs 2023)"}.`,b="Dietary fat does not make you fat — a calorie surplus does. At the same calories and protein, swapping carbs for fat does not change how much fat or muscle you gain; it moves glycogen and water (from a pound to a few on the scale). What fat does do is support testosterone and keep meals satisfying, so keep it at 20-35% of calories and do not drop below ~20% for long stretches.",w="Dietary fat does not make you fat — a calorie surplus does. At the same calories and protein, the carb/fat split does not change how much fat or muscle you gain, only glycogen and water weight. Keep fat at 20-35% of calories for hormones, satiety and vitamin absorption.",v="Don't under-fuel training: food minus exercise should stay above ~30 kcal per kg of lean mass a day. Missed or irregular periods are a warning sign, not a sign of progress.",k="A big, long deficit plus hard training is how low energy availability happens. Below ~30 kcal per kg of fat-free mass a day (food minus exercise), the hormone pulses that drive your cycle were disrupted within 5 days (Loucks & Thuma 2003). Missed or irregular periods are a red flag (IOC REDs consensus, Mountjoy 2023): keep the deficit moderate, protein high, and talk to a doctor if your cycle changes.",T="A big, long deficit is the fastest way to push your own testosterone down: in Ranger-school-type studies (Friedl 2000) men on ~1,000 kcal/day deficits with heavy training reached near-castrate levels, and a bodybuilder prepping to 4.5% body fat fell from 922 to 227 ng/dL (Rossow 2013). It recovers within days to weeks of eating normally again. Keep the deficit moderate and protein high.",E={contraception:{none:"None",combined:"Combined (pill/patch/ring)",progestin:"Progestin-only",hormonal_iud:"Hormonal IUD",copper_iud:"Copper IUD",other:"Other"},hormoneTherapy:{none:"None",estrogen:"Estrogen",estrogen_progestogen:"Estrogen + progestogen"}},A={contraception:"Hormonal contraception",hormoneTherapy:"Menopausal hormone therapy"},M="Sets the body-fat formulas, calorie burn, muscle-gain model, hormone ranges and milestones. Tap ⓘ to see exactly what changes.",S=" Menopause stage and contraception change the hormone reference values and the notes; Forge models no direct muscle effect from them because the studies don't show one.",L="Nothing here is medical advice. Pregnancy, postpartum, menopause and hormone therapy decisions belong with your clinician.",I=e=>` Your testosterone level raises the reachable ceiling by about ${e} FFMI (Kouri's steroid users averaged ~3 points above non-users; Forge maps 1,000 → 2,400 ng/dL to +0 → +2.0 and does not extrapolate; this mapping is an estimate, not a measured dose-response).`,C=" Natural testosterone in the female range isn't modelled to limit muscle gain.",N=", and testosterone follows your metabolic profile (an assumed average declines ~1%/yr with age; a lab value is aged ~1%/yr past 40 per the Massachusetts Male Aging Study, which only matters if it falls into the low range)",x=e=>`Energy availability (food minus exercise, per kg of lean mass) drops to about ${e} kcal/kg/day in this plan. ~45 is adequate; below ~30 is where measurable harm starts. That threshold comes from women (Loucks & Thuma 2003) and no male equivalent has been validated, but low energy availability costs bone density, hormones, sleep and training quality in men too (IOC REDs consensus 2023). Forge doesn't model those effects: treat this as a warning, not a target.`,R=(e,t,o)=>o?`Energy availability (food minus exercise, per kg of lean mass) drops to about ${e} kcal/kg/day. Low energy availability costs bone and recovery at any age (IOC REDs 2023); Forge doesn't model those effects.`:`Energy availability (food minus exercise, per kg of lean mass) drops to about ${e} kcal/kg/day in this projection${t?" from the start":""}. Below ~30, the hormone pulses that drive the menstrual cycle were disrupted within 5 days (Loucks & Thuma 2003); missed or irregular periods, bone loss and stalled progress follow (IOC REDs consensus 2023). Forge doesn't model those effects, so treat this plan as a warning: eat more around training or ease the deficit.`,F=e=>`Energy availability drops to about ${e} kcal per kg of lean mass a day. Below ~30 the hormone pulses that run the menstrual cycle were disrupted within five days (Loucks & Thuma 2003); missed periods, bone loss and stalled progress follow (IOC REDs 2023).`,D="usually costs regular periods and ",P=" for hormones",H="Under ~30 the hormones that run your cycle are disrupted (Loucks &amp; Thuma 2003; IOC REDs 2023)",O="That is below ~30, where reproductive and metabolic hormones (testosterone included) start to suffer. The ~30 threshold comes from Loucks &amp; Thuma 2003 in women; no equivalent number has been established in men, so treat it as a flag, not a line (IOC REDs 2023)",z=" with your testosterone",_=e=>`Not as stated. At the same calories and protein, dietary fat is no more fattening than carbohydrate — a surplus is what adds fat. In a surplus fat is stored most efficiently (90-95% of it over two weeks; Horton 1995), but surplus carbs end up as fat too, mostly by being burned in place of the fat you ate, and after three weeks the two stored the same (Lammert 2000). There IS a floor: men who drop from ~40% to ~20% of calories from fat lose a little testosterone (${e.totalTestosteroneSMD} SD, 95% CI ${e.totalTestosteroneCI[0]} to ${e.totalTestosteroneCI[1]}; Whittaker 2021), which is why Forge warns under ${e.floorPct}% and not over it. ${e.amdr[0]}-${e.amdr[1]}% is the recommended range.`,W="How far under maintenance you usually eat. Around 500 kcal/day stops lean-mass gain from lifting (Murphy & Koehler 2021); 1,000+ with a heavy training load is where testosterone starts falling hard (Friedl 2000). Leave blank if you eat at or above maintenance.",J="testosterone trials used 19–35-year-olds; ";function B(e,{COC_SHBG_ADD:t,COC_FREE_T_FACTOR:o}){const a=[];return e.combinedHormonal?a.push({id:"contraception",label:"Combined hormonal contraception",mult:1,note:`SHBG roughly doubles (+${t} nmol/L) and free testosterone drops ~${Math.round((1-o)*100)}% (Zimmerman 2014). The effect on muscle gain is unclear: one trial found slightly more quadriceps growth on the pill (Dalgaard 2019), an observational study found less lean gain (Riechman 2022), and performance differences are trivial (Elliott-Sale 2020). Forge models none.`}):e.contraception!=="none"&&a.push({id:"contraception",label:"Contraception",mult:1,note:"Progestin-only methods and IUDs have no established effect on muscle gain; Forge models none."}),e.mht&&a.push({id:"mht",label:"Menopausal hormone therapy",mult:1,note:"No clear effect on muscle mass (Javed 2019, 12 RCTs: −0.06 kg less lean lost, not significant), about 5% more strength (Greising 2009) and about 7% less abdominal fat (Salpeter 2006). Forge models no lean or fat change."}),a}export{D as ABS_PERIODS,J as AGE_FACTOR_T,C as AGE_NOTE_FEMALE,N as AGE_NOTE_MALE,L as CLINICIAN_LINE,W as DEFICIT_REF,H as EA_CARD_FEMALE,O as EA_CARD_MALE,b as FAT_TIP,w as FAT_TIP_FEMALE,k as FEMALE_DEFICIT_WARNING,S as FEMALE_FIELDS_HORMONES,A as FEMALE_HORMONE_FIELDS,E as FEMALE_HORMONE_LABELS,P as FOR_HORMONES,c as HORMONE_FEMALE,l as HORMONE_INSERTS,d as HORMONE_ITEM_IDS,m as KEPT_TEXT,T as MALE_DEFICIT_WARNING,g as NO_FATTENING,M as SEX_HINT,h as SIX_PACK_PERIODS,u as SIX_PACK_TIP_PERIODS,v as UNDERFUEL_TIP,z as WITH_YOUR_T,I as ceilingShiftNote,y as eaFemaleNote,F as eaLossFemale,f as eaMaleNote,R as eaPlanFemale,x as eaPlanMale,_ as fatFloorAnswer,p as fatFloorMale,B as femaleStatusFactors};
